"""客服 Agent 主流程：模型选择工具 -> 执行 -> 工具结果回填模型 -> 生成回答。

预约查询额外有一层本地解析：手机号 / 身份证号解析成 patient_ref、日期 / 科室 /
"第几条" 的槽位解析都在本机完成（完整手机号、证件号不得发给外部模型），
解析结果落到会话状态，用于连续追问。
"""

import re
from datetime import date, timedelta

from identity import find_identifiers, find_patient_ref, mask_for_model
from model_client import ModelClient
from tools.appointments import known_departments, list_appointments
from tools.bills import list_bills
from tools.medications import list_medications
from tools.patient_profile import patient_profile

TOOLS = {
    "patient_profile": patient_profile,
    "list_medications": list_medications,
    "list_bills": list_bills,
    "list_appointments": list_appointments,
}

RELATIVE_DAYS = {"今天": 0, "今日": 0, "明天": 1, "明日": 1, "后天": 2}
FULL_DATE_RE = re.compile(r"(\d{4})-(\d{1,2})-(\d{1,2})")
MONTH_DAY_RE = re.compile(r"(\d{1,2})月(\d{1,2})[日号]")
ORDINAL_RE = re.compile(r"第\s*([一二三四五六七八九十两\d]{1,3})\s*[条个]")
ORDINAL_DIGITS = {"一": 1, "二": 2, "两": 2, "三": 3, "四": 4, "五": 5,
                  "六": 6, "七": 7, "八": 8, "九": 9, "十": 10}


def parse_ordinal(text):
    """解析“第二条 / 第2个”这类序号；没有则返回 None。"""
    if not isinstance(text, str):
        return None
    match = ORDINAL_RE.search(text)
    if not match:
        return None
    token = match.group(1)
    return int(token) if token.isdigit() else ORDINAL_DIGITS.get(token)


def parse_date(text, today):
    """解析“明天”“11月18日”“2026-11-18”；没有日期则返回 None。"""
    if not isinstance(text, str):
        return None
    for word, delta in RELATIVE_DAYS.items():
        if word in text:
            return today + timedelta(days=delta)
    match = FULL_DATE_RE.search(text)
    if match:
        year, month, day = (int(part) for part in match.groups())
    else:
        match = MONTH_DAY_RE.search(text)
        if not match:
            return None
        year = today.year
        month, day = (int(part) for part in match.groups())
    try:
        return date(year, month, day)
    except ValueError:
        return None


def parse_department(text):
    """匹配院内已知科室名；长的排前面，避免“内科”命中“心内科”。"""
    if not isinstance(text, str):
        return None
    for name in sorted(known_departments(), key=len, reverse=True):
        if name in text:
            return name
    return None


def _leaf_texts(value):
    """收集工具结果里的字符串字段，用于判断模型回答是否用上了工具返回的内容。"""
    if isinstance(value, dict):
        for item in value.values():
            yield from _leaf_texts(item)
    elif isinstance(value, list):
        for item in value:
            yield from _leaf_texts(item)
    elif isinstance(value, str) and value:
        yield value


def format_appointment(row):
    return "%s %s %s（%s）" % (row["date"], row["time"], row["department"], row["status"])


def summarize_appointments(result, ordinal=None):
    """本地兜底摘要：只用工具返回的业务字段，不带原始手机号 / 证件号。"""
    if ordinal is not None:
        return "第 %d 条：%s。" % (ordinal, format_appointment(result))
    rows = result["appointments"]
    name = result.get("patient", {}).get("name", "")
    if not rows:
        return "%s没有符合条件的预约。" % name
    lines = "；".join(format_appointment(row) for row in rows)
    return "%s共 %d 条预约：%s。" % ("%s " % name if name else "", len(rows), lines)


class CustomerServiceAgent:
    def __init__(self, model_client=None):
        self.model = model_client or ModelClient()
        self.last_result = None
        self.session = {"patient_ref": None, "appointments": []}

    def _system_message(self):
        return {
            "role": "system",
            "content": ("你是医院客服助手。根据患者问题选择合适的工具，参数使用 patient_ref。"
                        "工具返回后用中文回答。不要编造工具未返回的信息。"
                        "患者身份与预约筛选条件已由服务端解析，工具结果中的身份信息已脱敏。"),
            "tools": sorted(TOOLS),
        }

    def _send(self, messages):
        """出境的请求统一脱敏：完整手机号、完整证件号不得发给外部模型。"""
        return self.model.send(mask_for_model(messages))

    def _tool_turn(self, user_text, name, arguments, result):
        """既有流程：工具结果回填模型，由模型组织回答。"""
        self.last_result = result
        return self._send([
            self._system_message(),
            {"role": "user", "content": user_text},
            {"role": "assistant", "tool_call": {"name": name, "arguments": arguments}},
            {"role": "tool", "name": name, "content": result},
        ])

    def answer(self, user_text, today=None):
        """处理一轮患者消息；today 便于测试相对日期（如“明天”）。"""
        today = today or date.today()
        identifiers = find_identifiers(user_text)
        patient_ref = find_patient_ref(user_text)
        if identifiers and not patient_ref:
            return "未找到该手机号或证件号对应的患者，请核对后重试。"
        if patient_ref:
            self.session["patient_ref"] = patient_ref
        if self._is_appointment_query(user_text):
            return self._answer_appointments(user_text, today, patient_ref)
        return self._answer_by_model(user_text)

    def _is_appointment_query(self, text):
        """预约意图：明确提到预约 / 挂号，或对上一条结果追问“第几条”。"""
        if not isinstance(text, str):
            return False
        return "预约" in text or "挂号" in text or parse_ordinal(text) is not None

    def _answer_appointments(self, user_text, today, patient_ref=None):
        ordinal = parse_ordinal(user_text)
        when = parse_date(user_text, today)
        department = parse_department(user_text)
        if ordinal and not (when or department or patient_ref):
            return self._answer_follow_up(user_text, ordinal)
        current = self.session["patient_ref"]
        if not current:
            return "请先提供您的手机号或身份证号，确认身份后再查询预约。"
        arguments = {"patient_ref": current}
        if when:
            arguments["date"] = when.isoformat()
        if department:
            arguments["department"] = department
        try:
            result = TOOLS["list_appointments"](**arguments)
        except PermissionError:
            return "当前登录身份无权查看该患者的预约。"
        self.session["appointments"] = result["appointments"]
        reply = self._tool_turn(user_text, "list_appointments", arguments, result)
        return self._grounded_reply(reply, result)

    def _answer_follow_up(self, user_text, ordinal):
        """连续追问：在上一轮预约列表里取第几条，再回填模型组织回答。"""
        rows = self.session["appointments"]
        if not rows:
            return "请先告诉我要查询谁的预约，再说第几条。"
        if ordinal > len(rows):
            return "上一次查询只有 %d 条预约。" % len(rows)
        row = rows[ordinal - 1]
        reply = self._tool_turn(user_text, "list_appointments",
                                {"patient_ref": self.session["patient_ref"], "row": ordinal},
                                row)
        return self._grounded_reply(reply, row, ordinal=ordinal)

    def _grounded_reply(self, reply, result, ordinal=None):
        """模型回答要用上工具返回的业务字段，用不上（或没有回答）就回退本地摘要。"""
        if isinstance(reply, str) and any(text in reply for text in _leaf_texts(result)):
            return reply
        return summarize_appointments(result, ordinal=ordinal)

    def _answer_by_model(self, user_text):
        first = self._send([
            self._system_message(),
            {"role": "user", "content": user_text},
        ])
        if not isinstance(first, dict) or "tool" not in first:
            return first if isinstance(first, str) else "请说明您想查询的内容。"

        name = first["tool"]
        if name not in TOOLS:
            return "暂不支持该查询。"
        arguments = first.get("arguments") or {}
        return self._tool_turn(user_text, name, arguments, TOOLS[name](**arguments))

