"""身份识别与脱敏：手机号 / 身份证号只在本机流转，完整值不得发给外部模型。"""

import re

from patient_store import find_by_identifier

# 身份证号（18 位）写在前面，避免手机号规则命中证件号中间的数字
IDENTIFIER_RE = re.compile(r"(?<!\d)(?:\d{17}[\dXx]|1[3-9]\d{9})(?!\d)")


def find_identifiers(text):
    """按出现顺序返回文本中的手机号 / 身份证号（原始值，仅限本机使用）。"""
    if not isinstance(text, str):
        return []
    return [match.group(0) for match in IDENTIFIER_RE.finditer(text)]


def find_patient_ref(text):
    """把文本中的手机号 / 身份证号解析成 patient_ref；解析不到返回 None。"""
    for token in find_identifiers(text):
        ref = find_by_identifier(token)
        if ref:
            return ref
    return None


def mask_identifier(value):
    """手机号保留前 3 后 4，证件号保留前 6 后 4，中间用 * 代替。"""
    if len(value) == 11:
        return value[:3] + "****" + value[-4:]
    return value[:6] + "*" * (len(value) - 10) + value[-4:]


def mask_text(text):
    if not isinstance(text, str):
        return text
    return IDENTIFIER_RE.sub(lambda match: mask_identifier(match.group(0)), text)


def mask_for_model(value):
    """递归脱敏任意待出境的数据（字符串 / 字典 / 列表），不修改入参。"""
    if isinstance(value, str):
        return mask_text(value)
    if isinstance(value, dict):
        return {key: mask_for_model(item) for key, item in value.items()}
    if isinstance(value, list):
        return [mask_for_model(item) for item in value]
    return value
